  if (!validInt(token) || BigInt(token) < BigInt(min)) {
    throw new ParseError(line, `${field} must be an integer of at least ${min}`)
  }
  return BigInt(token)
}

/**
 * Parses the limiter file text into policies, routes and events.
 * Throws ParseError on any violation, reporting the first one found
 * (in line order, and within a line, in the order fields appear).
 */
export function parseProgram(text) {
  let lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const policies = new Map() // name -> BucketPolicy | WindowPolicy
  const routes = [] // { prefix, policyNames: [] }
  const routePrefixes = new Set()
  const events = [] // { tick: BigInt, key }
  let seenEvent = false
  let lastTick = null

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i]
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'bucket') {
      if (seenEvent) throw new ParseError(lineNo, 'declarations must come before the first event')
      if (tokens.length !== 5) throw new ParseError(lineNo, 'expected bucket <name> <capacity> <refill> <per>')
      const [, name, capacityTok, refillTok, perTok] = tokens
      if (!NAME_RE.test(name)) throw new ParseError(lineNo, `invalid policy name ${name}`)
      const capacity = requireField(lineNo, 'capacity', capacityTok, 1)
      const refill = requireField(lineNo, 'refill', refillTok, 0)
      const per = requireField(lineNo, 'per', perTok, 1)
      if (policies.has(name)) throw new ParseError(lineNo, `policy ${name} is declared twice`)
      policies.set(name, new BucketPolicy(name, capacity, refill, per))
    } else if (directive === 'window') {
      if (seenEvent) throw new ParseError(lineNo, 'declarations must come before the first event')
      if (tokens.length !== 4) throw new ParseError(lineNo, 'expected window <name> <limit> <span>')
      const [, name, limitTok, spanTok] = tokens
      if (!NAME_RE.test(name)) throw new ParseError(lineNo, `invalid policy name ${name}`)
      const limit = requireField(lineNo, 'limit', limitTok, 0)
      const span = requireField(lineNo, 'span', spanTok, 1)
      if (policies.has(name)) throw new ParseError(lineNo, `policy ${name} is declared twice`)
      policies.set(name, new WindowPolicy(name, limit, span))
    } else if (directive === 'route') {
      if (seenEvent) throw new ParseError(lineNo, 'declarations must come before the first event')
      if (tokens.length < 3) throw new ParseError(lineNo, 'expected route <prefix> <policy>...')
      const prefix = tokens[1]
      const policyNames = tokens.slice(2)
      if (!NAME_RE.test(prefix)) throw new ParseError(lineNo, `invalid route prefix ${prefix}`)
      if (routePrefixes.has(prefix)) throw new ParseError(lineNo, `prefix ${prefix} is routed twice`)
      for (const pname of policyNames) {
        if (!policies.has(pname)) throw new ParseError(lineNo, `unknown policy ${pname}`)
      }
      routePrefixes.add(prefix)
      routes.push({ prefix, policyNames })
    } else if (directive === 'event') {
