      }
    }
  } else {
    const keys = [...stats.keys()].sort()
    let totalAllowed = 0
    let totalDenied = 0
    for (const key of keys) {
      const s = stats.get(key)
      totalAllowed += s.allowed
      totalDenied += s.denied
      lines.push(`${key} allowed=${s.allowed} denied=${s.denied}`)
    }
    lines.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
  }

  process.stdout.write(lines.length > 0 ? lines.join('\n') + '\n' : '')
  process.exit(0)
}

main()
